            ofd = os.open(stdout_file, os.O_WRONLY|os.O_CREAT|os.O_TRUNC)
            os.dup2(ofd, 1)
        if stderr_file:
            efd = os.open(stderr_file, os.O_WRONLY|os.O_CREAT|os.O_TRUNC)
            os.dup2(efd, 2)
        os.execv(argv[0], argv)
    out = b''
    start = time.time()
    pending = list(responders)
    while True:
        r, _, _ = select.select([fd], [], [], 0.1)
        if r:
            try:
                data = os.read(fd, 65536)
            except OSError:
                break
            if not data:
                break
            out += data
            sys.stderr.write('READ: %r\n' % data[:300])
        while pending and pending[0][0] in out:
            q, resp = pending.pop(0)
            sys.stderr.write('RESPOND: %r\n' % resp)
            os.write(fd, resp)
        if time.time() - start > timeout:
            os.kill(pid, signal.SIGKILL)
            break
    _, status = os.waitpid(pid, 0)
    return out, status, time.time() - start

def unesc(s):
    return s.encode().decode('unicode_escape').encode('latin1')

if __name__ == '__main__':
    argv = sys.argv[1:]
    responders = []
