        r = os.environ.get('R%d' % i)
        if q and r is not None:
            responders.append((unesc(q), unesc(r)))
    timeout = float(os.environ.get('TIMEOUT', '5'))
    out, status, elapsed = run(argv, responders, timeout=timeout,
        stdin_null=bool(os.environ.get('STDIN_NULL')),
        stdout_file=os.environ.get('STDOUT_FILE'), stderr_file=os.environ.get('STDERR_FILE'))
    sys.stdout.write(repr(out[:2000]) + '\n')
    sys.stdout.write('status=%r elapsed=%.2f\n' % (status, elapsed))
