package graph

import (
	"image"
	"image/color"
	"math"
)

// Point is a 2D point in pixel coordinates.
type Point struct{ X, Y float64 }

// Path is a collection of closed polygons (each a list of points).
type Path struct {
	subpaths [][]Point
	cur      []Point
}

// MoveTo starts a new subpath.
func (p *Path) MoveTo(x, y float64) {
	p.closeCur()
	p.cur = []Point{{x, y}}
}

// LineTo appends a straight segment.
func (p *Path) LineTo(x, y float64) {
	if p.cur == nil {
		p.cur = []Point{{x, y}}
		return
	}
	p.cur = append(p.cur, Point{x, y})
}

// QuadTo appends a quadratic bezier segment, flattened into lines.
func (p *Path) QuadTo(cx, cy, x, y float64) {
	if len(p.cur) == 0 {
		p.LineTo(x, y)
		return
	}
	p0 := p.cur[len(p.cur)-1]
	// number of segments based on control polygon length
	d := math.Hypot(cx-p0.X, cy-p0.Y) + math.Hypot(x-cx, y-cy)
	n := int(math.Ceil(math.Sqrt(d * 2)))
	if n < 3 {
		n = 3
	}
	if n > 24 {
		n = 24
	}
	for i := 1; i <= n; i++ {
		t := float64(i) / float64(n)
		mt := 1 - t
		px := mt*mt*p0.X + 2*mt*t*cx + t*t*x
		py := mt*mt*p0.Y + 2*mt*t*cy + t*t*y
		p.cur = append(p.cur, Point{px, py})
	}
}

// Close closes the current subpath.
func (p *Path) Close() { p.closeCur() }

func (p *Path) closeCur() {
	if len(p.cur) > 1 {
		p.subpaths = append(p.subpaths, p.cur)
	}
	p.cur = nil
}

// AddPolygon adds a closed polygon.
func (p *Path) AddPolygon(pts []Point) {
	p.closeCur()
	if len(pts) > 1 {
		cp := make([]Point, len(pts))
		copy(cp, pts)
		p.subpaths = append(p.subpaths, cp)
	}
}

// Bounds returns the bounding box of all points.
func (p *Path) Bounds() (minX, minY, maxX, maxY float64, ok bool) {
	p.closeCur()
	minX, minY = math.Inf(1), math.Inf(1)
	maxX, maxY = math.Inf(-1), math.Inf(-1)
	for _, sp := range p.subpaths {
		for _, pt := range sp {
			if pt.X < minX {
				minX = pt.X
			}
			if pt.X > maxX {
				maxX = pt.X
			}
			if pt.Y < minY {
				minY = pt.Y
			}
			if pt.Y > maxY {
				maxY = pt.Y
			}
		}
	}
	ok = len(p.subpaths) > 0
	return
}

// Rasterizer accumulates signed area coverage for anti-aliased filling.
type Rasterizer struct {
	w, h int
	acc  []float32
}

// NewRasterizer creates a rasterizer for a w x h pixel area.
func NewRasterizer(w, h int) *Rasterizer {
	return &Rasterizer{w: w, h: h, acc: make([]float32, (w+2)*h)}
}

func (r *Rasterizer) reset() {
	for i := range r.acc {
		r.acc[i] = 0
	}
}

func (r *Rasterizer) line(x0, y0, x1, y1 float64) {
	if y0 == y1 {
		return
	}
	dir := float32(1)
	if y0 > y1 {
		dir = -1
		x0, y0, x1, y1 = x1, y1, x0, y0
	}
	// clip vertically
	if y1 <= 0 || y0 >= float64(r.h) {
		return
	}
	dxdy := (x1 - x0) / (y1 - y0)
	if y0 < 0 {
		x0 -= y0 * dxdy
		y0 = 0
	}
	if y1 > float64(r.h) {
		x1 += (float64(r.h) - y1) * dxdy
		y1 = float64(r.h)
	}
	fw := float64(r.w)
	stride := r.w + 2
	x := x0
	y0i := int(y0)
	y1c := int(math.Ceil(y1))
	if y1c > r.h {
		y1c = r.h
	}
	for y := y0i; y < y1c; y++ {
		linestart := y * stride
		dy := math.Min(float64(y+1), y1) - math.Max(float64(y), y0)
		xnext := x + dxdy*dy
		d := float32(dy) * dir
		xa, xb := x, xnext
		if xa > xb {
			xa, xb = xb, xa
		}
		// clamp horizontally
		if xa < 0 {
			xa = 0
		}
		if xb < 0 {
			xb = 0
		}
		if xa > fw {
			xa = fw
		}
		if xb > fw {
			xb = fw
		}
		x0floor := math.Floor(xa)
		x0i := int(x0floor)
		x1ceil := math.Ceil(xb)
		x1i := int(x1ceil)
		if x1i <= x0i+1 {
			xmf := float32(0.5*(xa+xb) - x0floor)
			r.acc[linestart+x0i] += d - d*xmf
			r.acc[linestart+x0i+1] += d * xmf
		} else {
			s := 1 / (xb - xa)
			x0f := xa - x0floor
			a0 := float32(0.5 * s * (1 - x0f) * (1 - x0f))
			x1f := xb - x1ceil + 1.0
			am := float32(0.5 * s * x1f * x1f)
			r.acc[linestart+x0i] += d * a0
			if x1i == x0i+2 {
				r.acc[linestart+x0i+1] += d * (1.0 - a0 - am)
			} else {
				a1 := float32(s * (1.5 - x0f))
				r.acc[linestart+x0i+1] += d * (a1 - a0)
				for xi := x0i + 2; xi < x1i-1; xi++ {
					r.acc[linestart+xi] += d * float32(s)
				}
				a2 := a1 + float32(float64(x1i-x0i-3)*s)
				r.acc[linestart+x1i-1] += d * (1.0 - a2 - am)
			}
			r.acc[linestart+x1i] += d * am
		}
		x = xnext
	}
}

// Fill rasterizes the path and calls fn(x, y, coverage) for every pixel with
// non-zero coverage. Coverage is in [0, 1].
func (r *Rasterizer) Fill(p *Path, fn func(x, y int, cov float32)) {
	p.closeCur()
	if len(p.subpaths) == 0 {
		return
	}
	minX, minY, maxX, maxY, _ := p.Bounds()
	if maxY < 0 || minY >= float64(r.h) || maxX < 0 || minX >= float64(r.w) {
		return
	}
	r.reset()
	for _, sp := range p.subpaths {
		n := len(sp)
		for i := 0; i < n; i++ {
			a := sp[i]
			b := sp[(i+1)%n]
			r.line(a.X, a.Y, b.X, b.Y)
		}
	}
	y0 := int(math.Max(0, math.Floor(minY)))
	y1 := int(math.Min(float64(r.h), math.Ceil(maxY)))
	stride := r.w + 2
	for y := y0; y < y1; y++ {
		var acc float32
		row := r.acc[y*stride : y*stride+stride]
		for x := 0; x < r.w; x++ {
			acc += row[x]
			c := acc
			if c < 0 {
				c = -c
			}
			if c > 1 {
				c = 1
			}
			if c > 0.0005 {
				fn(x, y, c)
			}
		}
	}
}

// Canvas is an RGBA drawing surface with anti-aliased primitives.
type Canvas struct {
	Img *image.RGBA
	ras *Rasterizer
	// Offset translates drawing coordinates (used to stack graphs).
	OffX, OffY int
}

// NewCanvas allocates a canvas of the given size.
func NewCanvas(w, h int) *Canvas {
	return &Canvas{Img: image.NewRGBA(image.Rectangle{Max: image.Point{w, h}}), ras: NewRasterizer(w, h)}
}

// Color is a non-premultiplied RGBA color.
type Color = color.NRGBA

// blend composites col with coverage cov over the pixel at x, y.
func (c *Canvas) blend(x, y int, col Color, cov float32) {
	a := float32(col.A) / 255 * cov
	if a <= 0 {
		return
	}
	i := c.Img.PixOffset(x, y)
	pix := c.Img.Pix[i : i+4 : i+4]
	// src premultiplied
	sr := float32(col.R) * a
	sg := float32(col.G) * a
	sb := float32(col.B) * a
	sa := 255 * a
	ia := 1 - a
	pix[0] = uint8(sr + float32(pix[0])*ia + 0.5)
	pix[1] = uint8(sg + float32(pix[1])*ia + 0.5)
	pix[2] = uint8(sb + float32(pix[2])*ia + 0.5)
	pix[3] = uint8(sa + float32(pix[3])*ia + 0.5)
}

// FillPath fills a path with a color.
func (c *Canvas) FillPath(p *Path, col Color) {
	if col.A == 0 {
		return
	}
	if c.OffX != 0 || c.OffY != 0 {
		p.closeCur()
		for _, sp := range p.subpaths {
			for i := range sp {
				sp[i].X += float64(c.OffX)
				sp[i].Y += float64(c.OffY)
			}
		}
	}
	c.ras.Fill(p, func(x, y int, cov float32) {
		c.blend(x, y, col, cov)
	})
}

// FillRect fills an axis aligned rectangle [x0,x1) x [y0,y1).
func (c *Canvas) FillRect(x0, y0, x1, y1 float64, col Color) {
	var p Path
	p.AddPolygon([]Point{{x0, y0}, {x1, y0}, {x1, y1}, {x0, y1}})
	c.FillPath(&p, col)
}

func signedArea(pts []Point) float64 {
	var a float64
	n := len(pts)
	for i := 0; i < n; i++ {
		p := pts[i]
		q := pts[(i+1)%n]
		a += p.X*q.Y - q.X*p.Y
	}
	return a / 2
}

func orient(pts []Point) []Point {
	if signedArea(pts) < 0 {
		for i, j := 0, len(pts)-1; i < j; i, j = i+1, j-1 {
			pts[i], pts[j] = pts[j], pts[i]
		}
	}
	return pts
}

// StrokeStyle controls how polylines are stroked.
type StrokeStyle struct {
	Width     float64
	Color     Color
	Dash      []float64 // alternating on/off lengths; nil for solid
	SquareCap bool
}

// StrokePolyline strokes an open polyline.
func (c *Canvas) StrokePolyline(pts []Point, st StrokeStyle) {
	if len(pts) < 2 || st.Color.A == 0 || st.Width <= 0 {
		return
	}
	if len(st.Dash) > 0 {
		for _, seg := range dashSplit(pts, st.Dash) {
			c.strokeSolid(seg, st.Width, st.Color, false)
		}
		return
	}
	c.strokeSolid(pts, st.Width, st.Color, st.SquareCap)
}

func (c *Canvas) strokeSolid(pts []Point, width float64, col Color, square bool) {
	hw := width / 2
	var p Path
	for i := 0; i+1 < len(pts); i++ {
		a, b := pts[i], pts[i+1]
		dx, dy := b.X-a.X, b.Y-a.Y
		l := math.Hypot(dx, dy)
		if l == 0 {
			continue
		}
		ux, uy := dx/l, dy/l
		ex, ey := 0.0, 0.0
		if square {
			ex, ey = ux*hw, uy*hw
		}
		sx, sy := a.X, a.Y
		tx, ty := b.X, b.Y
		if square {
			if i == 0 {
				sx, sy = sx-ex, sy-ey
			}
			if i+2 == len(pts) {
				tx, ty = tx+ex, ty+ey
			}
		}
		nx, ny := -uy*hw, ux*hw
		quad := []Point{{sx + nx, sy + ny}, {tx + nx, ty + ny}, {tx - nx, ty - ny}, {sx - nx, sy - ny}}
		p.AddPolygon(orient(quad))
		// round join at interior vertices
		if i+2 < len(pts) {
			p.AddPolygon(orient(circlePoly(b.X, b.Y, hw)))
		}
	}
	c.FillPath(&p, col)
}

func circlePoly(cx, cy, r float64) []Point {
	n := 8
	if r > 2 {
		n = int(8 + r*2)
	}
	pts := make([]Point, n)
	for i := 0; i < n; i++ {
		t := 2 * math.Pi * float64(i) / float64(n)
		pts[i] = Point{cx + r*math.Cos(t), cy + r*math.Sin(t)}
	}
	return pts
}

// dashSplit splits a polyline into dash pieces following the pattern.
func dashSplit(pts []Point, dash []float64) [][]Point {
	var out [][]Point
	di := 0
	remain := dash[0]
	on := true
	var cur []Point
	if on {
		cur = []Point{pts[0]}
	}
	for i := 0; i+1 < len(pts); i++ {
		a, b := pts[i], pts[i+1]
		segLen := math.Hypot(b.X-a.X, b.Y-a.Y)
		pos := 0.0
		for segLen-pos > remain {
			pos += remain
			t := pos / segLen
			pt := Point{a.X + (b.X-a.X)*t, a.Y + (b.Y-a.Y)*t}
			if on {
				cur = append(cur, pt)
				out = append(out, cur)
				cur = nil
			} else {
				cur = []Point{pt}
			}
			on = !on
			di = (di + 1) % len(dash)
			remain = dash[di]
		}
		remain -= segLen - pos
		if on {
			cur = append(cur, b)
		}
	}
	if on && len(cur) > 1 {
		out = append(out, cur)
	}
	return out
}
