package graph

import (
	"math"
	"testing"
)

func TestRectCoverage(t *testing.T) {
	r := NewRasterizer(10, 10)
	var p Path
	p.AddPolygon([]Point{{2, 2}, {6, 2}, {6, 5}, {2, 5}})
	sum := 0.0
	r.Fill(&p, func(x, y int, c float32) {
		if c < 0.999 || c > 1.001 {
			t.Errorf("pixel %d,%d coverage %v", x, y, c)
		}
		sum += float64(c)
	})
	if math.Abs(sum-12) > 1e-3 {
		t.Errorf("area %v", sum)
	}
	// half pixel offsets
	var q Path
	q.AddPolygon([]Point{{2.5, 2.5}, {6.5, 2.5}, {6.5, 5.5}, {2.5, 5.5}})
	sum = 0
	r.Fill(&q, func(x, y int, c float32) { sum += float64(c) })
	if math.Abs(sum-12) > 1e-3 {
		t.Errorf("area2 %v", sum)
	}
	// triangle clipped
	var tr Path
	tr.AddPolygon([]Point{{-5, -5}, {15, -5}, {5, 15}})
	sum = 0
	r.Fill(&tr, func(x, y int, c float32) { sum += float64(c) })
	if sum < 50 || sum > 100 {
		t.Errorf("tri area %v", sum)
	}
}

func TestStroke(t *testing.T) {
	c := NewCanvas(20, 20)
	c.StrokePolyline([]Point{{2, 10}, {18, 10}}, StrokeStyle{Width: 2, Color: Color{255, 0, 0, 255}, SquareCap: true})
	// pixels y=9 and y=10 should be fully red from x=1..18
	for x := 1; x <= 18; x++ {
		for _, y := range []int{9, 10} {
			i := c.Img.PixOffset(x, y)
			if c.Img.Pix[i+3] != 255 || c.Img.Pix[i] != 255 {
				t.Errorf("pixel %d,%d = %v", x, y, c.Img.Pix[i:i+4])
			}
		}
	}
	for _, y := range []int{8, 11} {
		i := c.Img.PixOffset(5, y)
		if c.Img.Pix[i+3] != 0 {
			t.Errorf("pixel 5,%d should be empty: %v", y, c.Img.Pix[i:i+4])
		}
	}
}
