func (f Font) scale() float64 { return f.Size / fontUnitsPerEm }

func lookupGlyph(r rune) (glyphDef, bool) {
	g, ok := glyphData[r]
	if ok {
		return g, true
	}
	if r == 0xB5 || r == 0x3BC {
		if g, ok := glyphData[0xB5]; ok {
			return g, true
		}
	}
	g, ok = glyphData['?']
	return g, ok
}

// contourPoints flattens a quadratic TrueType contour into pixel coordinates.
func (f Font) contourPath(p *Path, c glyphContour, ox, oy float64) {
	n := len(c) / 3
	if n == 0 {
		return
	}
	s := f.scale()
	type pt struct {
		x, y float64
		on   bool
	}
	pts := make([]pt, n)
	for i := 0; i < n; i++ {
		pts[i] = pt{ox + float64(c[3*i])*s, oy - float64(c[3*i+1])*s, c[3*i+2] != 0}
	}
	// find first on-curve point
	start := -1
	for i, q := range pts {
		if q.on {
			start = i
			break
		}
	}
	var sx, sy float64
	if start < 0 {
		// all off-curve: start at midpoint of first two
		sx = (pts[0].x + pts[1].x) / 2
		sy = (pts[0].y + pts[1].y) / 2
		start = 0
	} else {
		sx, sy = pts[start].x, pts[start].y
	}
	p.MoveTo(sx, sy)
	var ctrl *pt
	for k := 1; k <= n; k++ {
		q := pts[(start+k)%n]
		if q.on {
			if ctrl != nil {
				p.QuadTo(ctrl.x, ctrl.y, q.x, q.y)
				ctrl = nil
			} else {
				p.LineTo(q.x, q.y)
			}
		} else {
			if ctrl != nil {
				mx, my := (ctrl.x+q.x)/2, (ctrl.y+q.y)/2
				p.QuadTo(ctrl.x, ctrl.y, mx, my)
			}
			cq := q
			ctrl = &cq
		}
	}
	if ctrl != nil {
		p.QuadTo(ctrl.x, ctrl.y, sx, sy)
	}
	p.Close()
}

// TextPath builds the outline path of a string with its baseline origin at x, y.
func (f Font) TextPath(text string, x, y float64) *Path {
	var p Path
	s := f.scale()
	cursor := x
	for _, r := range text {
		g, ok := lookupGlyph(r)
		if !ok {
			continue
		}
		for _, c := range g.contours {
			f.contourPath(&p, c, cursor, y)
		}
		cursor += float64(g.adv) * s
	}
	return &p
}

// Box is an integer rectangle.
type Box struct{ Top, Left, Right, Bottom int }

func (b Box) Width() int  { return absInt(b.Right - b.Left) }
func (b Box) Height() int { return absInt(b.Bottom - b.Top) }

func absInt(v int) int {
	if v < 0 {
		return -v
	}
	return v
}

// Measure returns the ink bounding box of the text, mimicking a renderer that
// measures the outline control points.
func (f Font) Measure(text string) Box {
	s := f.scale()
	l, t, r, b := 10e6, 10e6, -10e6, -10e6
	cursor := 0.0
	for _, rn := range text {
		g, ok := lookupGlyph(rn)
		if !ok {
			continue
		}
		for _, c := range g.contours {
			n := len(c) / 3
			for i := 0; i < n; i++ {
				px := cursor + float64(c[3*i])*s
				py := -float64(c[3*i+1]) * s
				l = math.Min(l, px)
				r = math.Max(r, px)
				t = math.Min(t, py)
				b = math.Max(b, py)
			}
		}
		cursor += float64(g.adv) * s
	}
	if r < l {
		// no ink
		return Box{}
	}
	if l < 0 {
		r -= l
		l = 0
	}
	if t < 0 {
		b -= t
		t = 0
	}
	return Box{Top: int(math.Ceil(t)), Left: int(math.Ceil(l)), Right: int(math.Ceil(r)), Bottom: int(math.Ceil(b))}
}

// Advance returns the total advance width of the text in pixels.
func (f Font) Advance(text string) float64 {
	s := f.scale()
	w := 0.0
	for _, rn := range text {
		g, ok := lookupGlyph(rn)
		if !ok {
			continue
		}
		w += float64(g.adv) * s
	}
	return w
}

// Ascent returns the distance from baseline to the top of capital letters.
func (f Font) Ascent() float64 {
	g, ok := glyphData['H']
	if !ok {
		return f.Size * 0.72
	}
	maxY := 0
	for _, c := range g.contours {
		for i := 0; i+2 < len(c); i += 3 {
			if int(c[i+1]) > maxY {
				maxY = int(c[i+1])
			}
		}
	}
	return float64(maxY) * f.scale()
}

// Text draws text with the baseline origin at x, y.
func (c *Canvas) Text(f Font, text string, x, y float64, col Color) {
	p := f.TextPath(text, x, y)
	c.FillPath(p, col)
}
