{"command":"cd /workspace && cat > graph/format.go <<'EOF'
package graph

import (
	"fmt"
	"math"
	"strconv"
	"strings"
)

var siPrefixes = map[int]string{
	-24: "y", -21: "z", -18: "a", -15: "f", -12: "p", -9: "n", -6: "µ", -3: "m",
	0: "", 3: "k", 6: "M", 9: "G", 12: "T", 15: "P", 18: "E", 21: "Z", 24: "Y",
}

func logn(n, b float64) float64 { return math.Log(n) / math.Log(b) }

// computeSI scales a value to an SI prefix.
func computeSI(input float64) (float64, string) {
	if input == 0 {
		return 0, ""
	}
	mag := math.Abs(input)
	exponent := math.Floor(logn(mag, 10))
	exponent = math.Floor(exponent/3) * 3
	value := mag / math.Pow(10, exponent)
	if value == 1000.0 {
		exponent += 3
		value = mag / math.Pow(10, exponent)
	}
	value = math.Copysign(value, input)
	prefix := siPrefixes[int(exponent)]
	return value, prefix
}

func stripTrailingZeros(s string) string {
	if !strings.ContainsRune(s, '.') {
		return s
	}
	offset := len(s) - 1
	for offset > 0 {
		if s[offset] == '.' {
			offset--
			break
		}
		if s[offset] != '0' {
			break
		}
		offset--
	}
	return s[:offset+1]
}

func stripTrailingDigits(s string, digits int) string {
	if i := strings.Index(s, "."); i >= 0 {
		if digits <= 0 {
			return s[:i]
		}
		i++
		if i+digits >= len(s) {
			return s
		}
		return s[:i+digits]
	}
	return s
}

func ftoaWithDigits(num float64, digits int) string {
	return stripTrailingZeros(stripTrailingDigits(strconv.FormatFloat(num, 'f', 6, 64), digits))
}

// SIFormat formats a value with an SI prefix and up to two decimals.
func SIFormat(v float64) string {
	value, prefix := computeSI(v)
	return ftoaWithDigits(value, 2) + " " + prefix
}

// FloatFormat formats a value with two decimals.
func FloatFormat(v float64) string {
	return fmt.Sprintf("%.2f", v)
}
