cat > graph/chart.go <<'EOF'
package graph

import (
	"errors"
	"math"
)

// Series is a named sequence of values to plot.
type Series struct {
	Name   string
	Values []float64
	Marker bool
}

// Graph is one chart made of several series sharing the same axes.
type Graph struct {
	Series []Series
}

// Colors
var (
	colorBlue       = Color{0, 116, 217, 255}
	colorGreen      = Color{0, 217, 101, 255}
	colorRed        = Color{217, 0, 116, 255}
	colorCyan       = Color{0, 217, 210, 255}
	colorOrange     = Color{217, 101, 0, 255}
	colorAltBlue    = Color{106, 195, 203, 255}
	colorAltGreen   = Color{42, 190, 137, 255}
	colorAltGray    = Color{110, 128, 139, 255}
	colorAltYellow  = Color{240, 174, 90, 255}
	colorWhite      = Color{255, 255, 255, 255}
	colorText       = Color{180, 180, 180, 255}
	colorAxis       = Color{180, 180, 180, 128}
	colorLegendFill = Color{0, 0, 0, 100}
	colorMarker     = Color{110, 128, 139, 100}

	defaultColors   = []Color{colorBlue, colorGreen, colorRed, colorCyan, colorOrange}
	alternateColors = []Color{colorAltBlue, colorAltGreen, colorAltGray, colorAltYellow, colorBlue, colorGreen, colorRed, colorCyan, colorOrange}
)

func seriesColor(i int) Color {
	if i < len(defaultColors) {
		return defaultColors[i]
	}
	return alternateColors[(i-len(defaultColors))%len(alternateColors)]
}

func withAlpha(c Color, a uint8) Color { c.A = a; return c }

// Layout constants.
const (
	paddingTop     = 5
	paddingLeft    = 0
	paddingRight   = 0
	paddingBottom  = 5
	xAxisMargin    = 10
	yAxisMargin    = 10
	tickLength     = 4
	minTickHSpace  = 20
	minTickVSpace  = 20
	tickSanity     = 1024
	lineWidth      = 2
	axisFontSize   = 13.0
	legendFontSize = 10.4
	annotFontSize  = 10.4
	annotDelta     = 10
	annotPadTop    = 3
	annotPadBottom = 3
	annotPadLeft   = 2
	annotPadRight  = 2
	legendPad      = 5
	legendTextGap  = 5
	legendLineMin  = 25
	legendVSpace   = 5
	markerLabelW   = 3
	markerLabelH   = 6
)

type rng struct {
	min, max float64
	domain   int
}

func (r rng) delta() float64 { return r.max - r.min }

// translate maps a value into [0, domain].
func (r rng) translate(v float64) int {
	ratio := (v - r.min) / r.delta()
	return int(math.Ceil(ratio * float64(r.domain)))
}

type tick struct {
	value float64
	label string
}

func roundToForDelta(delta float64) float64 {
	for cursor := math.Pow(10, 10); cursor > 0; cursor /= 10 {
		if delta > cursor {
			return cursor / 10
		}
	}
	return 0
}

func roundUp(value, roundTo float64) float64 {
	return math.Ceil(value/roundTo) * roundTo
}

func generateTicks(r rng, vertical bool, f Font, format func(float64) string, labelBox func(string) Box) []tick {
	var ticks []tick
	ticks = append(ticks, tick{r.min, format(r.min)})
	lb := labelBox(format(r.min))
	var tickSize float64
	if vertical {
		tickSize = float64(lb.Height() + minTickVSpace)
	} else {
		tickSize = float64(lb.Width() + minTickHSpace)
	}
	domain := float64(r.domain)
	remainder := domain - tickSize*2
	intermediate := int(math.Floor(remainder / tickSize))
	delta := math.Abs(r.delta())
	tickStep := delta / float64(intermediate)
	roundTo := roundToForDelta(delta) / 10
	if intermediate > tickSanity {
		intermediate = tickSanity
	}
	for x := 1; x < intermediate; x++ {
		v := r.min + roundUp(tickStep*float64(x), roundTo)
		ticks = append(ticks, tick{v, format(v)})
	}
	ticks = append(ticks, tick{r.max, format(r.max)})
	return ticks
}

func growBox(a, b Box) Box {
	return Box{Top: minInt(a.Top, b.Top), Left: minInt(a.Left, b.Left), Right: maxInt(a.Right, b.Right), Bottom: maxInt(a.Bottom, b.Bottom)}
}

func outerConstrain(b, bounds, other Box) Box {
	nb := b
	if other.Top < bounds.Top {
		nb.Top = b.Top + (bounds.Top - other.Top)
	}
	if other.Left < bounds.Left {
		nb.Left = b.Left + (bounds.Left - other.Left)
	}
	if other.Right > bounds.Right {
		nb.Right = b.Right - (other.Right - bounds.Right)
	}
	if other.Bottom > bounds.Bottom {
		nb.Bottom = b.Bottom - (other.Bottom - bounds.Bottom)
	}
	return nb
}

func minInt(a, b int) int {
	if a < b {
		return a
	}
	return b
}
func maxInt(a, b int) int {
	if a > b {
		return a
	}
	return b
}

type chartLayout struct {
	g        Graph
	data     []Series // non marker series
	colors   []Color
	markers  []Series
	w, h     int
	xr, yr   rng
	cb       Box
	bounds   Box
	xt, yt   []tick
	axisFont Font
	legFont  Font
	annFont  Font
}

// ErrNoSeries is returned when a graph has no series.
var ErrNoSeries = errors.New("please provide at least one series")

func newLayout(g Graph, w, h int) (*chartLayout, error) {
	l := &chartLayout{g: g, w: w, h: h}
	l.axisFont = Font{Size: axisFontSize}
	l.legFont = Font{Size: legendFontSize}
	l.annFont = Font{Size: annotFontSize}
	idx := 0
	for _, s := range g.Series {
		if s.Marker {
			l.markers = append(l.markers, s)
			continue
		}
		l.data = append(l.data, s)
		l.colors = append(l.colors, seriesColor(idx))
		idx++
	}
	if len(l.data) == 0 {
		return nil, ErrNoSeries
	}
	// ranges
	minX, maxX := math.Inf(1), math.Inf(-1)
	minY, maxY := math.Inf(1), math.Inf(-1)
	for _, s := range l.data {
		if len(s.Values) > 0 {
			minX = math.Min(minX, 0)
			maxX = math.Max(maxX, float64(len(s.Values)-1))
		}
		for _, v := range s.Values {
			minY = math.Min(minY, v)
			maxY = math.Max(maxY, v)
		}
	}
	if minY == maxY {
		minY -= 0.05
		maxY += 0.05
	}
	l.xr = rng{min: minX, max: maxX}
	l.yr = rng{min: minY, max: maxY}
	xd := l.xr.delta()
	if math.IsInf(xd, 0) {
		return nil, errors.New("infinite x-range delta")
	}
	if math.IsNaN(xd) {
		return nil, errors.New("NaN x-range delta")
	}
	if xd == 0 {
		return nil, errors.New("zero x-range delta; there needs to be at least (2) values")
	}
	yd := l.yr.delta()
	if math.IsInf(yd, 0) {
		return nil, errors.New("infinite y-range delta")
	}
	if math.IsNaN(yd) {
		return nil, errors.New("NaN y-range delta")
	}
	if yd == 0 {
		return nil, errors.New("zero y-range delta")
	}
	l.bounds = Box{Top: paddingTop, Left: paddingLeft, Right: w - paddingRight, Bottom: h - paddingBottom}
	l.cb = l.bounds
	l.setDomains()
	for pass := 0; pass < 2; pass++ {
		l.genTicks()
		l.adjustForAxes()
		l.setDomains()
	}
	l.adjustForAnnotations()
	l.setDomains()
	l.genTicks()
	return l, nil
}

func (l *chartLayout) hasMarkers() bool {
	for _, m := range l.markers {
		for _, v := range m.Values {
			if v != 0 {
				return true
			}
		}
	}
	return false
}

func (l *chartLayout) setDomains() {
	l.xr.domain = l.cb.Right - l.cb.Left - 1
	l.yr.domain = l.cb.Bottom - l.cb.Top
}

func (l *chartLayout) xLabelBox(label string) Box {
	if l.hasMarkers() {
		return Box{Right: markerLabelW, Bottom: markerLabelH}
	}
	return l.axisFont.Measure(label)
}

func (l *chartLayout) genTicks() {
	l.xt = generateTicks(l.xr, false, l.axisFont, FloatFormat, l.xLabelBox)
	l.yt = generateTicks(l.yr, true, l.axisFont, SIFormat, l.axisFont.Measure)
}

func (l *chartLayout) measureXAxis() Box {
	cb := l.cb
	left, right, bottom := math.MaxInt32, 0, 0
	for _, t := range l.xt {
		tb := l.xLabelBox(t.label)
		tx := cb.Left + l.xr.translate(t.value)
		ty := cb.Bottom + xAxisMargin + tb.Height()
		ltx := tx - tb.Width()>>1
		rtx := tx + tb.Width()>>1
		left = minInt(left, ltx)
		right = maxInt(right, rtx)
		bottom = maxInt(bottom, ty)
	}
	return Box{Top: cb.Bottom, Left: left, Right: right, Bottom: bottom}
}

func (l *chartLayout) measureYAxis() Box {
	cb := l.cb
	tx := cb.Right + yAxisMargin
	minx, maxx, miny, maxy := math.MaxInt32, 0, math.MaxInt32, 0
	for _, t := range l.yt {
		ly := cb.Bottom - l.yr.translate(t.value)
		tb := l.axisFont.Measure(t.label)
		tbh2 := tb.Height() >> 1
		minx = cb.Right
		maxx = maxInt(maxx, tx+tb.Width())
		miny = minInt(miny, ly-tbh2)
		maxy = maxInt(maxy, ly+tbh2)
	}
	return Box{Top: miny, Left: minx, Right: maxx, Bottom: maxy}
}

func (l *chartLayout) adjustForAxes() {
	outer := l.cb
	outer = growBox(outer, l.measureXAxis())
	outer = growBox(outer, l.measureYAxis())
	l.cb = outerConstrain(l.cb, l.bounds, outer)
}

func (l *chartLayout) lastPoint(s Series) (int, int, string) {
	n := len(s.Values)
	last := s.Values[n-1]
	lx := l.cb.Left + l.xr.translate(float64(n-1))
	ly := l.cb.Bottom - l.yr.translate(last)
	return lx, ly, SIFormat(last)
}

func (l *chartLayout) measureAnnotation(lx, ly int, label string) Box {
	tb := l.annFont.Measure(label)
	hth := tb.Height() >> 1
	top := ly - (annotPadTop + hth)
	right := lx + annotPadLeft + annotPadRight + tb.Width() + annotDelta + 1
	bottom := ly + annotPadBottom + hth
	return Box{Top: top, Left: lx, Right: right, Bottom: bottom}
}

func (l *chartLayout) adjustForAnnotations() {
	outer := l.cb
	for _, s := range l.data {
		lx, ly, label := l.lastPoint(s)
		outer = growBox(outer, l.measureAnnotation(lx, ly, label))
	}
	l.cb = outerConstrain(l.cb, l.bounds, outer)
}

// draw renders the laid out chart onto the canvas (which may be offset).
func (l *chartLayout) draw(c *Canvas) {
	cb := l.cb
	f := l.axisFont
	axisStroke := StrokeStyle{Width: lineWidth, Color: colorAxis, SquareCap: true}

	// left edge line
	c.FillRect(float64(cb.Left-2), float64(cb.Top), float64(cb.Left), float64(cb.Bottom), colorAxis)

	markers := l.hasMarkers()
	if !markers {
		// x axis
		c.StrokePolyline([]Point{{float64(cb.Left), float64(cb.Bottom)}, {float64(cb.Right), float64(cb.Bottom)}}, axisStroke)
		for _, t := range l.xt {
			tx := cb.Left + l.xr.translate(t.value)
			c.StrokePolyline([]Point{{float64(tx), float64(cb.Bottom)}, {float64(tx), float64(cb.Bottom + tickLength)}}, axisStroke)
			tb := f.Measure(t.label)
			ty := cb.Bottom + xAxisMargin + tb.Height()
			c.Text(f, t.label, float64(tx-tb.Width()>>1), float64(ty), colorText)
		}
	} else {
		for _, m := range l.markers {
			for i, v := range m.Values {
				if v == 0 {
					continue
				}
				x := float64(cb.Left + l.xr.translate(float64(i)))
				c.StrokePolyline([]Point{{x, float64(cb.Bottom)}, {x, float64(cb.Top)}}, StrokeStyle{Width: lineWidth, Color: colorMarker, Dash: []float64{2, 2}})
			}
		}
	}

	// y axis (right side)
	c.StrokePolyline([]Point{{float64(cb.Right), float64(cb.Top)}, {float64(cb.Right), float64(cb.Bottom)}}, axisStroke)
	for _, t := range l.yt {
		ly := cb.Bottom - l.yr.translate(t.value)
		c.StrokePolyline([]Point{{float64(cb.Right), float64(ly)}, {float64(cb.Right + tickLength), float64(ly)}}, axisStroke)
		tb := f.Measure(t.label)
		c.Text(f, t.label, float64(cb.Right+yAxisMargin), float64(ly+tb.Height()>>1), colorText)
	}

	// series
	for si, s := range l.data {
		col := l.colors[si]
		n := len(s.Values)
		pts := make([]Point, n)
		for i, v := range s.Values {
			pts[i] = Point{float64(cb.Left + l.xr.translate(float64(i))), float64(cb.Bottom - l.yr.translate(v))}
		}
		// fill to the zero line
		y0 := minInt(cb.Bottom, cb.Bottom-l.yr.translate(0))
		poly := make([]Point, 0, n+2)
		poly = append(poly, pts...)
		poly = append(poly, Point{pts[n-1].X, float64(y0)}, Point{pts[0].X, float64(y0)})
		var fp Path
		fp.AddPolygon(poly)
		c.FillPath(&fp, withAlpha(col, 20))
		c.StrokePolyline(pts, StrokeStyle{Width: lineWidth, Color: col, SquareCap: true})
	}

	// annotations
	for si, s := range l.data {
		col := l.colors[si]
		lx, ly, label := l.lastPoint(s)
		l.drawAnnotation(c, lx, ly, label, col)
	}

	l.drawLegend(c)
}

func (l *chartLayout) drawAnnotation(c *Canvas, lx, ly int, label string, col Color) {
	tb := l.annFont.Measure(label)
	hth := tb.Height() >> 1
	const sw = 1
	textX := lx + annotPadLeft + annotDelta + sw
	textY := ly + hth
	ltx, lty := lx+sw, ly
	ttx, tty := lx+annotDelta+sw, ly-hth-annotPadTop
	rtx, rty := ttx+tb.Width()+annotPadRight+annotPadLeft, tty
	rbx, rby := rtx, ly+hth+annotPadBottom
	tbx, tby := ttx, rby
	poly := []Point{{float64(ltx), float64(lty)}, {float64(ttx), float64(tty)}, {float64(rtx), float64(rty)}, {float64(rbx), float64(rby)}, {float64(tbx), float64(tby)}}
	var p Path
	p.AddPolygon(poly)
	c.FillPath(&p, col)
	closed := append(poly, poly[0])
	c.StrokePolyline(closed, StrokeStyle{Width: sw, Color: col})
	c.Text(l.annFont, label, float64(textX), float64(textY), colorWhite)
}

func (l *chartLayout) drawLegend(c *Canvas) {
	cb := l.cb
	f := l.legFont
	type entry struct {
		label string
		tb    Box
		col   Color
	}
	var entries []entry
	for si, s := range l.data {
		label := s.Name + ": " + SIFormat(s.Values[len(s.Values)-1])
		entries = append(entries, entry{label, f.Measure(label), l.colors[si]})
	}
	contentLeft := cb.Left + legendPad
	contentTop := cb.Top + legendPad
	contentRight := contentLeft
	contentBottom := contentTop
	for i, e := range entries {
		if i > 0 {
			contentBottom += legendVSpace
		}
		contentBottom += e.tb.Height()
		right := contentLeft + e.tb.Width() + legendTextGap + legendLineMin
		contentRight = maxInt(contentRight, right)
	}
	box := Box{Top: cb.Top, Left: cb.Left, Right: contentRight + legendPad, Bottom: contentBottom + legendPad}
	c.FillRect(float64(box.Left), float64(box.Top), float64(box.Right), float64(box.Bottom), colorLegendFill)
	ycursor := contentTop
	tx := contentLeft
	for i, e := range entries {
		if i > 0 {
			ycursor += legendVSpace
		}
		ty := ycursor + e.tb.Height()
		c.Text(f, e.label, float64(tx), float64(ty), colorText)
		th2 := e.tb.Height() >> 1
		lx := tx + e.tb.Width() + legendTextGap
		ly := ty - th2
		lx2 := contentRight - legendPad
		c.StrokePolyline([]Point{{float64(lx), float64(ly)}, {float64(lx2), float64(ly)}}, StrokeStyle{Width: lineWidth, Color: e.col})
		ycursor += e.tb.Height()
	}
}

// RenderGraph draws one graph into the canvas region starting at offY.
func RenderGraph(c *Canvas, g Graph, w, h, offY int) error {
	l, err := newLayout(g, w, h)
	if err != nil {
		return err
	}
	c.OffX, c.OffY = 0, offY
	l.draw(c)
	c.OffX, c.OffY = 0, 0
	return nil
}
