	return value, prefix
}

func stripTrailingZeros(s string) string {
	if !strings.ContainsRune(s, '.') {
		return s
	}
	offset := len(s) - 1
	for offset > 0 {
		if s[offset] == '.' {
			offset--
			break
		}
		if s[offset] != '0' {
			break
		}
		offset--
	}
	return s[:offset+1]
}

func stripTrailingDigits(s string, digits int) string {
	if i := strings.Index(s, "."); i >= 0 {
		if digits <= 0 {
			return s[:i]
		}
		i++
		if i+digits >= len(s) {
			return s
		}
		return s[:i+digits]
	}
	return s
}

func ftoaWithDigits(num float64, digits int) string {
	return stripTrailingZeros(stripTrailingDigits(strconv.FormatFloat(num, 'f', 6, 64), digits))
}

// SIFormat formats a value with an SI prefix and up to two decimals.
func SIFormat(v float64) string {
	value, prefix := computeSI(v)
	return ftoaWithDigits(value, 2) + " " + prefix
}

// FloatFormat formats a value with two decimals.
func FloatFormat(v float64) string {
	return fmt.Sprintf("%.2f", v)
}
