const maxColors = 254

type rgb struct{ r, g, b uint8 }

type entry struct {
	c     rgb
	count int
}

type box struct {
	entries []entry
	count   int
}

func (b *box) ranges() (dr, dg, db int) {
	minr, ming, minb := 255, 255, 255
	maxr, maxg, maxb := 0, 0, 0
	for _, e := range b.entries {
		if int(e.c.r) < minr {
			minr = int(e.c.r)
		}
		if int(e.c.r) > maxr {
			maxr = int(e.c.r)
		}
		if int(e.c.g) < ming {
			ming = int(e.c.g)
		}
		if int(e.c.g) > maxg {
			maxg = int(e.c.g)
		}
		if int(e.c.b) < minb {
			minb = int(e.c.b)
		}
		if int(e.c.b) > maxb {
			maxb = int(e.c.b)
		}
	}
	return maxr - minr, maxg - ming, maxb - minb
}

func (b *box) mean() rgb {
	var sr, sg, sb, n int64
	for _, e := range b.entries {
		sr += int64(e.c.r) * int64(e.count)
		sg += int64(e.c.g) * int64(e.count)
		sb += int64(e.c.b) * int64(e.count)
		n += int64(e.count)
	}
	if n == 0 {
		return rgb{}
	}
	return rgb{uint8((sr + n/2) / n), uint8((sg + n/2) / n), uint8((sb + n/2) / n)}
}

// quantize builds a palette of at most maxColors colors using median cut and
// returns the palette and a map from packed color to palette index.
func quantize(hist map[uint32]int) ([]rgb, map[uint32]int) {
	all := &box{}
	for k, n := range hist {
		all.entries = append(all.entries, entry{rgb{uint8(k >> 16), uint8(k >> 8), uint8(k)}, n})
		all.count += n
	}
	// deterministic order
	sort.Slice(all.entries, func(i, j int) bool {
		a, b := all.entries[i].c, all.entries[j].c
		if a.r != b.r {
			return a.r < b.r
		}
		if a.g != b.g {
			return a.g < b.g
		}
		return a.b < b.b
	})
	boxes := []*box{all}
	for len(boxes) < maxColors {
		// pick the box with the largest pixel count that can be split
		best := -1
		for i, bx := range boxes {
			if len(bx.entries) < 2 {
				continue
			}
			if best < 0 || bx.count > boxes[best].count {
				best = i
			}
		}
		if best < 0 {
			break
		}
		bx := boxes[best]
		dr, dg, db := bx.ranges()
		switch {
		case dr >= dg && dr >= db:
			sort.Slice(bx.entries, func(i, j int) bool { return bx.entries[i].c.r < bx.entries[j].c.r })
		case dg >= db:
			sort.Slice(bx.entries, func(i, j int) bool { return bx.entries[i].c.g < bx.entries[j].c.g })
		default:
			sort.Slice(bx.entries, func(i, j int) bool { return bx.entries[i].c.b < bx.entries[j].c.b })
		}
		half := bx.count / 2
		acc := 0
		split := 0
		for i, e := range bx.entries {
			if acc >= half && i > 0 {
				break
			}
			acc += e.count
			split = i + 1
		}
		if split >= len(bx.entries) {
			split = len(bx.entries) - 1
		}
		if split < 1 {
			split = 1
		}
		left := &box{entries: bx.entries[:split]}
		right := &box{entries: bx.entries[split:]}
		for _, e := range left.entries {
			left.count += e.count
		}
		for _, e := range right.entries {
			right.count += e.count
		}
		boxes[best] = left
		boxes = append(boxes, right)
	}
	// sort palette by luminance for a stable, pleasant order
	sort.Slice(boxes, func(i, j int) bool {
		a, b := boxes[i].mean(), boxes[j].mean()
		la := int(a.r)*299 + int(a.g)*587 + int(a.b)*114
		lb := int(b.r)*299 + int(b.g)*587 + int(b.b)*114
