package data

import (
	"fmt"
	"strings"
)

// Field describes one value path with its options.
type Field struct {
	ID      string // full spec of the field (options and path)
	Name    string // path only
	Counter bool
	Marker  bool
}

// Spec is a group of fields plotted on the same graph.
type Spec struct {
	Fields []Field
}

// ParseSpec parses a FIELD_SPEC argument: fields separated by '+', each
// optionally prefixed with comma separated options and a colon.
func ParseSpec(spec string) (Spec, error) {
	var s Spec
	for _, fs := range strings.Split(spec, "+") {
		f := Field{ID: fs, Name: fs}
		if i := strings.LastIndex(fs, ":"); i >= 0 {
			f.Name = fs[i+1:]
			for _, opt := range strings.Split(fs[:i], ",") {
				switch opt {
				case "counter":
					f.Counter = true
				case "marker":
					f.Marker = true
				default:
					return s, fmt.Errorf("invalid field option: %s", opt)
				}
			}
		}
		s.Fields = append(s.Fields, f)
	}
	return s, nil
}

// ParseSpecs parses all positional arguments.
func ParseSpecs(args []string) ([]Spec, error) {
	specs := make([]Spec, 0, len(args))
	for _, a := range args {
		s, err := ParseSpec(a)
		if err != nil {
			return nil, err
		}
		specs = append(specs, s)
	}
	return specs, nil
}
