package data

import (
	"bufio"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"time"
)

// ReadStdin reads one JSON object per line from r until EOF.
func ReadStdin(r io.Reader, p *Points) error {
	sc := bufio.NewScanner(r)
	for sc.Scan() {
		var v interface{}
		if err := json.Unmarshal(sc.Bytes(), &v); err != nil {
			return fmt.Errorf("input error: %v", err)
		}
		if err := p.Push(v); err != nil {
			return err
		}
	}
	if err := sc.Err(); err != nil {
		return fmt.Errorf("input error: %v", err)
	}
	return nil
}

func fetch(url string, p *Points) error {
	resp, err := http.Get(url)
	if err != nil {
		return fmt.Errorf("input error: %v", err)
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return fmt.Errorf("input error: %v", err)
	}
	var v interface{}
	if err := json.Unmarshal(body, &v); err != nil {
		return fmt.Errorf("input error: %v", err)
	}
	return p.Push(v)
}

// FetchURL fetches url immediately and then at every interval until stop is
// closed. It returns on the first error.
func FetchURL(url string, interval time.Duration, p *Points, stop <-chan struct{}) error {
	if err := fetch(url, p); err != nil {
		return err
	}
	t := time.NewTicker(interval)
	defer t.Stop()
	for {
		select {
		case <-t.C:
			if err := fetch(url, p); err != nil {
				return err
			}
		case <-stop:
			return nil
		}
	}
}
