				cur.WriteRune(c)
			}
			continue
		}
		switch c {
		case '"', '\'':
			inQuote = true
			quote = c
		case '.':
			tokens = append(tokens, cur.String())
			cur.Reset()
		default:
			cur.WriteRune(c)
		}
	}
	tokens = append(tokens, cur.String())
	// empty intermediate tokens stand for a literal dot key
	for i := 0; i < len(tokens)-1; i++ {
		if tokens[i] == "" {
			tokens[i] = "."
		}
	}
	return tokens
}

// Query resolves a dotted path inside a decoded JSON value.
func Query(v interface{}, path string) (interface{}, error) {
	if path == "." {
		return v, nil
	}
	ctx := v
	for _, tok := range splitPath(path) {
		if len(tok) >= 3 && tok[0] == '[' && tok[len(tok)-1] == ']' {
			index, err := strconv.Atoi(tok[1 : len(tok)-1])
			if err != nil {
				return nil, err
			}
			arr, ok := ctx.([]interface{})
			if !ok {
				return nil, errors.New(fmt.Sprint(tok, " is not an array. ", arr))
			}
			if index >= len(arr) {
				return nil, errors.New(fmt.Sprint(tok, " index out of range."))
			}
			if index < 0 {
				ctx = float64(0)
				continue
			}
			ctx = arr[index]
			continue
		}
		obj, ok := ctx.(map[string]interface{})
		if !ok {
			return nil, errors.New(fmt.Sprint(tok, " is not an object. ", obj))
		}
		val, ok := obj[tok]
		if !ok {
			return nil, errors.New(fmt.Sprint(tok, " does not exist."))
		}
		ctx = val
	}
	return ctx, nil
}
