package data

import (
	"fmt"
	"sync"
)

// Points stores the recent values of each field as fixed size series.
type Points struct {
	mu     sync.Mutex
	steps  int
	specs  []Spec
	values map[string][]float64
	last   map[string]float64
	seen   map[string]bool
}

// NewPoints allocates storage for the given specs.
func NewPoints(specs []Spec, steps int) *Points {
	p := &Points{steps: steps, specs: specs, values: map[string][]float64{}, last: map[string]float64{}, seen: map[string]bool{}}
	for _, s := range specs {
		for _, f := range s.Fields {
			if _, ok := p.values[f.ID]; !ok {
				p.values[f.ID] = make([]float64, steps)
			}
		}
	}
	return p
}

// Push extracts all fields from a decoded JSON value and appends them.
func (p *Points) Push(v interface{}) error {
	p.mu.Lock()
	defer p.mu.Unlock()
	for _, s := range p.specs {
		for _, f := range s.Fields {
			raw, err := Query(v, f.Name)
			if err != nil {
				return fmt.Errorf("cannot get %s: %v", f.Name, err)
			}
			val, ok := raw.(float64)
			if !ok {
				return fmt.Errorf("invalid type %s: %T", f.Name, raw)
			}
			if f.Counter {
				d := val - p.last[f.ID]
				if !p.seen[f.ID] {
					d = 0
				}
				p.last[f.ID] = val
				val = d
			}
			p.seen[f.ID] = true
			ring := p.values[f.ID]
			if len(ring) > 0 {
				copy(ring, ring[1:])
				ring[len(ring)-1] = val
			}
		}
	}
	return nil
}

// Get returns a copy of the values recorded for a field.
func (p *Points) Get(id string) []float64 {
	p.mu.Lock()
	defer p.mu.Unlock()
	out := make([]float64, p.steps)
	copy(out, p.values[id])
	return out
}

// Specs returns the specs.
func (p *Points) Specs() []Spec { return p.specs }
