var (
	urlFlag      = flag.String("url", "", "URL to fetch every second. Read JSON objects from stdin if not specified.")
	intervalFlag = flag.Duration("interval", time.Second, "When url is provided, defines the interval between fetches. Note that counter fields are computed based on this interval.")
	stepsFlag    = flag.Int("steps", 100, "Number of values to plot.")
	rowsFlag     = flag.Int("rows", 0, "Limits the height of the graph output.")
)

func usage() {
	out := flag.CommandLine.Output()
	fmt.Fprintln(out, "Usage: jplot [OPTIONS] FIELD_SPEC [FIELD_SPEC...]:")
	fmt.Fprintln(out, "")
	fmt.Fprintln(out, "OPTIONS:")
	flag.PrintDefaults()
	fmt.Fprintln(out, "")
	fmt.Fprintln(out, "FIELD_SPEC: [<option>[,<option>...]:]path")
	fmt.Fprintln(out, "  option:")
	fmt.Fprintln(out, "    - counter: Computes the difference with the last value. The value must increase monotonically.")
	fmt.Fprintln(out, "    - marker: When the value is none-zero, a vertical line is drawn.")
	fmt.Fprintln(out, "  path:")
	fmt.Fprintln(out, "    JSON field path (eg: field.sub-field).")
}

func fatal(args ...interface{}) {
	fmt.Println(append([]interface{}{"jplot: "}, args...)...)
	os.Exit(1)
}

func main() {
	flag.Usage = usage
	flag.Parse()

	if !term.Supported() {
		fatal("iTerm2, Kitty, or DRCS Sixel graphics required")
	}
	if flag.NArg() == 0 {
		usage()
		os.Exit(1)
	}
	specs, err := data.ParseSpecs(flag.Args())
	if err != nil {
		fatal("Cannot parse spec: ", err)
	}
	dp := data.NewPoints(specs, *stepsFlag)

	exit := make(chan struct{})
	sigs := make(chan os.Signal, 1)
	signal.Notify(sigs, os.Interrupt, syscall.SIGTERM)
	if *urlFlag != "" {
		go func() {
			if err := data.FetchURL(*urlFlag, *intervalFlag, dp, nil); err != nil {
				fatal("Data source error: ", err)
			}
		}()
		go func() {
			<-sigs
			close(exit)
		}()
	} else {
		if term.IsTerminal(os.Stdin) {
			fatal("neither --url nor stdin is provided")
		}
		go func() {
			if err := data.ReadStdin(os.Stdin, dp); err != nil {
				fatal("Data source error: ", err)
			}
			close(exit)
		}()
	}

	done := make(chan struct{})
	go func() {
		defer close(done)
		loop(dp, exit)
	}()
	<-done
}

func loop(dp *data.Points, exit <-chan struct{}) {
	t := time.NewTicker(time.Second)
	defer t.Stop()
	prepared := false
	rows := 0
	for {
		select {
		case <-t.C:
			if !prepared {
				rows = prepare(*rowsFlag)
				prepared = true
				defer cleanup(rows)
			}
			fmt.Print("\x1b[s")
			render(dp, *rowsFlag)
			fmt.Print("\x1b[u")
		case <-exit:
			if !prepared {
				render(dp, *rowsFlag)
			}
			return
		}
	}
}

// prepare hides the cursor and reserves space for the graphs.
func prepare(rows int) int {
	fmt.Print("\x1b[?25l")
	if rows == 0 {
		r, err := term.TermRows()
		if err != nil {
			fatal("Cannot get window size: ", err)
		}
		rows = r
	}
	fmt.Print(strings.Repeat("\n", rows))
	fmt.Printf("\x1b[%dA", rows)
	return rows
}

func cleanup(rows int) {
	fmt.Printf("\x1b[?25h\x1b[%dB\n", rows)
}

func render(dp *data.Points, rows int) {
	width, height, err := term.Size(rows)
	if err != nil {
		fatal("Cannot get window size: ", err)
	}
	var dash graph.Dash
	for _, s := range dp.Specs() {
		var g graph.Graph
		for _, f := range s.Fields {
			g.Series = append(g.Series, graph.Series{Name: f.Name, Values: dp.Get(f.ID), Marker: f.Marker})
		}
		dash.Graphs = append(dash.Graphs, g)
	}
	bw := bufio.NewWriter(os.Stdout)
	defer bw.Flush()
	err = term.Write(bw, width, height, func(w io.Writer) error {
		return dash.RenderPNG(w, width, height)
	})
	if err != nil {
		fatal("cannot render graph: ", err)
	}
}
