package data

import (
	"encoding/json"
	"testing"
)

func TestQuery(t *testing.T) {
	var v interface{}
	src := `{"a":1,"b":{"c":2,"d":{"e":5}},"s":"str","arr":[1,{"k":2},[3]],"":7,"x.y":9,"z":{"":8,".":3},".":4,"q":{"r":{"":{"":6}}}}`
	if err := json.Unmarshal([]byte(src), &v); err != nil {
		t.Fatal(err)
	}
	cases := []struct {
		path string
		want interface{}
		err  string
	}{
		{"a", 1.0, ""},
		{"b.c", 2.0, ""},
		{"x.y.z", nil, "x does not exist."},
		{"a.b", nil, "b is not an object. map[]"},
		{"b.c.d", nil, "d is not an object. map[]"},
		{`"x.y"`, 9.0, ""},
		{`'x.y'`, 9.0, ""},
		{"z.", 8.0, ""},
		{"b.", nil, " does not exist."},
		{"..b", nil, ". is not an object. map[]"},
		{"z..", nil, " is not an object. map[]"},
		{"q.r.", nil, ""},
		{"arr.[1].k", 2.0, ""},
		{"arr.[2].[0]", 3.0, ""},
		{"arr.[3]", nil, "[3] index out of range."},
		{"arr.[-1]", 0.0, ""},
		{"b.[0]", nil, "[0] is not an array. []"},
		{"arr.[x]", nil, `strconv.Atoi: parsing "x": invalid syntax`},
		{"arr.[]", nil, "[] is not an object. map[]"},
	}
	for _, c := range cases {
		got, err := Query(v, c.path)
		if c.err != "" {
			if err == nil || err.Error() != c.err {
				t.Errorf("%q: got err %v, want %q", c.path, err, c.err)
			}
			continue
		}
		if err != nil {
			t.Errorf("%q: unexpected error %v", c.path, err)
			continue
		}
		if c.want != nil && got != c.want {
			t.Errorf("%q: got %v, want %v", c.path, got, c.want)
		}
	}
	if r, err := Query(v, "."); err != nil || r == nil {
		t.Errorf(". should return the root")
	}
}

func TestParseSpec(t *testing.T) {
	s, err := ParseSpec("counter,marker:cpu.STime+mem")
	if err != nil {
		t.Fatal(err)
	}
	if len(s.Fields) != 2 || !s.Fields[0].Counter || !s.Fields[0].Marker || s.Fields[0].Name != "cpu.STime" || s.Fields[1].Name != "mem" {
		t.Errorf("unexpected spec %+v", s)
	}
	if _, err := ParseSpec("foo:a"); err == nil || err.Error() != "invalid field option: foo" {
		t.Errorf("unexpected error %v", err)
	}
}

func TestCounter(t *testing.T) {
	specs, _ := ParseSpecs([]string{"counter:a"})
	p := NewPoints(specs, 4)
	for _, v := range []float64{5, 7, 10} {
		if err := p.Push(map[string]interface{}{"a": v}); err != nil {
			t.Fatal(err)
		}
	}
	got := p.Get("counter:a")
	want := []float64{0, 0, 2, 3}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("got %v want %v", got, want)
		}
	}
}
